// AvgustovStory 1.1-dev.11j: recipes for the armour / weapon tier pass (BALANCE_PLAN.md, night of 2026-11-19).
// Stats live in startup_scripts/avgustov_balance.js (generated by tools/balance). This file moves items between eras.
// 1. Netherite comes AFTER steel: the vanilla 4 scrap + 4 gold craft and Create Metalwork's molten-netherite alloying are
//    removed; a superheated Create mixer turns 4 scrap + 2 gold + 2 steel into an ingot. Netherite armour, Fantasy Armor,
//    Fantasy Weapons, the gear sword and every boss-trophy set (netherite base) become post-steel (tiers T5-T6).
//    Netherite found in loot (bastions) stays a reward for the risk.
// 2. Diamond armour needs one Create precision mechanism per piece (end of the brass era), which fills the empty
//    factory/rails eras with the T3 tier (diamond 20 / 8 and its variants abyssal, resonarium, neptunium).
// 3. Immersive Armors steampunk is made of brass instead of gold (its quest already sits in the brass era).
// 4. Cheap Epic Knights sets (chainmail, lamellar, cuirassier, half armour, hussar, crusader, platemail, norman helmet,
//    shishak, kettle hat, great helm, face helmet, brigandine) lose their steel: iron ingots, Create iron sheets (c:plates/iron),
//    vanilla chains and iron nuggets. They were iron-level armour behind the steel era; now they are early variety (T0-T1).
//    The XIV century knight set and its bascinet take brass sheets (T2). Knight / gothic / kastenbrust / ceremonial /
//    jousting / Maximilian keep steel (T4-T5).
// 5. Epic Knights flails (chain morning stars) of non-steel materials take a vanilla chain instead of a steel chain.
// 6. Aquaculture neptunium armour (diamond-level, made from fished neptunium, not diamonds) also needs a precision
//    mechanism per piece, like diamond armour (critique: it bypassed the diamond gate).
// 7. Upgrade chain (critique: players hate throwing away enchanted gear): Epic Knights gothic / kastenbrust (knight plate is the Maximilian base)
//    plate goes to netherite on the smithing table (netherite template + piece + netherite ingot), enchantments kept.
ServerEvents.recipes(event => {
  const C = event.recipes.create
  const id = s => 'avgustov:tier/' + s

  // 1. netherite after steel
  event.remove({ id: 'minecraft:netherite_ingot' })
  event.remove({ id: /^createmetalwork:mixing\/alloying\/molten_netherite/ })
  C.mixing('minecraft:netherite_ingot', ['4x minecraft:netherite_scrap', '2x minecraft:gold_ingot', '2x #c:ingots/steel']).superheated().id(id('netherite_ingot'))

  // 2. diamond armour + precision mechanism
  const D = 'minecraft:diamond', P = 'create:precision_mechanism'
  const diamond = {
    helmet: ['DPD', 'D D'],
    chestplate: ['D D', 'DPD', 'DDD'],
    leggings: ['DPD', 'D D', 'D D'],
    boots: ['D D', 'DPD'],
  }
  for (const [piece, pattern] of Object.entries(diamond)) {
    event.remove({ id: 'minecraft:diamond_' + piece })
    event.shaped('minecraft:diamond_' + piece, pattern, { D: D, P: P }).id(id('diamond_' + piece))
  }

  // 3. steampunk = brass
  event.replaceInput({ output: /^immersive_armors:steampunk_(helmet|chestplate|leggings|boots)$/ }, 'minecraft:gold_ingot', 'create:brass_ingot')

  // 4. cheap Epic Knights sets on iron
  const ironSets = /^magistuarmory:(chainmail_(helmet|chestplate|leggings|boots)|lamellar_(chestplate|boots)|lamellar_rows|cuirassier_(helmet|chestplate|leggings|boots)|halfarmor_chestplate|barbute|wingedhussar_chestplate|crusader_(chestplate|leggings|boots)|platemail_(chestplate|leggings|boots)|norman_helmet|shishak|kettlehat|greathelm|face_helmet|brigandine_chestplate)$/
  event.replaceInput({ output: ironSets }, '#c:ingots/steel', '#c:ingots/iron')
  event.replaceInput({ output: ironSets }, '#c:plates/steel', '#c:plates/iron')
  event.replaceInput({ output: ironSets }, '#c:nuggets/steel', '#c:nuggets/iron')
  event.replaceInput({ output: ironSets }, '#magistuarmory:chainmails/steel', 'minecraft:chain')
  event.replaceInput({ output: ironSets }, '#magistuarmory:small_plates/steel', '#c:nuggets/iron')
  event.replaceInput({ output: ironSets }, '#magistuarmory:lamellar_rows/steel', 'magistuarmory:lamellar_rows')
  const brassSets = /^magistuarmory:(xivcenturyknight_(chestplate|leggings|boots)|bascinet)$/
  event.replaceInput({ output: brassSets }, '#c:plates/steel', '#c:plates/brass')
  event.replaceInput({ output: brassSets }, '#magistuarmory:chainmails/steel', 'minecraft:chain')

  // 5. flails without steel
  event.replaceInput({ output: /^magistuarmory:(wood|stone|iron|gold|diamond|copper)_chainmorgenstern$/ }, '#magistuarmory:chains/steel', 'minecraft:chain')

  // 6. neptunium + precision mechanism
  const nep = { helmet: ['NPN', 'N N'], chestplate: ['N N', 'NPN', 'NNN'], leggings: ['NPN', 'N N', 'N N'], boots: ['N N', 'NPN'] }
  for (const [piece, pattern] of Object.entries(nep)) {
    event.remove({ id: 'aquaculture:neptunium_' + piece })
    event.shaped('aquaculture:neptunium_' + piece, pattern, { N: '#c:ingots/neptunium', P: P }).id(id('neptunium_' + piece))
  }

  // 7. steel plate -> netherite, enchantments kept (smithing transform copies components)
  // knight plate + armet are the base of Epic Knights' Maximilian (same inputs on the smithing table), so only gothic and
  // kastenbrust plate upgrade to netherite (quest audit 2026-11-19: the two recipes collided)
  const plate = { helmet: ['sallet', 'grand_bascinet'], chestplate: ['gothic_chestplate', 'kastenbrust_chestplate'],
    leggings: ['gothic_leggings', 'kastenbrust_leggings'], boots: ['gothic_boots', 'kastenbrust_boots'] }
  for (const [piece, bases] of Object.entries(plate)) for (const b of bases)
    event.smithing('minecraft:netherite_' + piece, 'minecraft:netherite_upgrade_smithing_template', 'magistuarmory:' + b, 'minecraft:netherite_ingot').id(id('plate_to_netherite_' + b))
})
